#include "player/SprintState.h"
#include <iostream>
namespace{int fail(const char* message){std::cerr<<message<<'\n';return 1;}}
int main(){SprintState sprint;if(sprint.movementSpeed()!=5.f||std::string(sprint.hudText())!="OFF")return fail("walking speed or HUD state failed");sprint.toggle();if(!sprint.wanted())return fail("shift did not toggle sprint wanted");sprint.evaluate(true,true);if(!sprint.active()||sprint.movementSpeed()!=10.f||std::string(sprint.hudText())!="ON")return fail("eligible sprint speed or HUD state failed");sprint.evaluate(false,true);if(sprint.active()||!sprint.wanted())return fail("W release did not preserve wanted state");sprint.evaluate(true,true);if(!sprint.active())return fail("W repress did not reactivate sprint");sprint.evaluate(true,false);if(sprint.active()||!sprint.wanted())return fail("ineligible sprint became active");sprint.cancel();sprint.forwardPressed(1.f);sprint.forwardPressed(1.3f);if(!sprint.wanted())return fail("exact 300 ms double-W boundary failed");sprint.cancel();sprint.forwardPressed(2.f);sprint.forwardPressed(2.3001f);if(sprint.wanted())return fail("late double-W incorrectly activated sprint");return 0;}
